param([ValidateSet('preview','test','live')][string]$Mode='preview',[switch]$OwnerApproved,[int]$ExpectedRecipientCount=0)
$ErrorActionPreference='Stop';if($Mode-eq'live'-and(-not$OwnerApproved-or$ExpectedRecipientCount-lt1)){throw'Live blast requires explicit owner approval and exact recipient count.'}
$repo=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path;$secure=Join-Path $repo 'output\release\secure'
function Read-Secret($Name){$s=Get-Content -LiteralPath(Join-Path $secure "$Name.dpapi")-Raw|ConvertTo-SecureString;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p)}}
try{$env:AFFIMATIK_BACKUP_DB_PASSWORD=Read-Secret 'supabase-db-password';$env:RESEND_API_KEY=Read-Secret 'resend-api-key';$env:AFFIMATIK_SUPABASE_CA=Join-Path $repo 'output\release\tools\supabase-prod-ca-2021.crt';$env:APP_BASE_URL='https://affimatik.online';$env:AFFIMATIK_CAMPAIGN_TEST_EMAIL='admin@affimatik.online';$env:AFFIMATIK_LIVE_CAMPAIGN_AUTHORIZED=if($OwnerApproved){'true'}else{'false'};$env:AFFIMATIK_EXPECTED_RECIPIENT_COUNT=$ExpectedRecipientCount;Push-Location $repo;try{& node scripts/release/next-10-email-campaign.mjs $Mode;if($LASTEXITCODE-ne0){throw "Campaign runner failed ($LASTEXITCODE)."}}finally{Pop-Location}}finally{foreach($n in @('AFFIMATIK_BACKUP_DB_PASSWORD','RESEND_API_KEY','AFFIMATIK_SUPABASE_CA','APP_BASE_URL','AFFIMATIK_CAMPAIGN_TEST_EMAIL','AFFIMATIK_LIVE_CAMPAIGN_AUTHORIZED','AFFIMATIK_EXPECTED_RECIPIENT_COUNT')){Remove-Item "Env:$n" -ErrorAction SilentlyContinue}}
